<?php
require __DIR__.'/../app/bootstrap.php';refresh_user();require_login('admin');
if($_SERVER['REQUEST_METHOD']==='POST'){
 verify_csrf();$action=post_value('action');
 if($action==='create'){$email=post_value('email');$role=post_value('role');$status=post_value('status');if(!filter_var($email,FILTER_VALIDATE_EMAIL)||!in_array($role,['User','Admin'],true)||!in_array($status,['Active','Suspended'],true)){flash('error','Enter a valid email and account options.');redirect('/admin/users.php');}$temporary=bin2hex(random_bytes(6));$hash=password_hash($temporary,PASSWORD_DEFAULT);try{$stmt=db()->prepare('INSERT INTO users(email,password_hash,role,status) VALUES(?,?,?,?)');$stmt->bind_param('ssss',$email,$hash,$role,$status);$stmt->execute();$sent=send_notice('account_registration',$email,['email'=>$email,'password'=>$temporary,'login_url'=>'/']);flash($sent?'success':'error',$sent?'Account created. A temporary password was emailed to '.$email.'.':'Account created, but the welcome email could not be sent. Configure mail settings and reset the password before sharing access.');}catch(mysqli_sql_exception $ex){flash('error',$ex->getCode()===1062?'That email address already has an account.':'Could not create that user.');}redirect('/admin/users.php');}
}
$q=trim($_GET['q']??'');$like='%'.$q.'%';$stmt=db()->prepare('SELECT id,email,role,status,created_at FROM users WHERE email LIKE ? ORDER BY id DESC');$stmt->bind_param('s',$like);$stmt->execute();$users=$stmt->get_result()->fetch_all(MYSQLI_ASSOC);
render_header('Users Management','admin');page_title('Users Management','Manage access to the client print workspace.');
?><div class="section-heading users-toolbar"><div><div class="eyebrow">ACCOUNT DIRECTORY</div><h2>All users <span class="count-pill"><?=count($users)?></span></h2></div><a class="button button-admin" href="#create-user">＋ Create new user</a></div><form method="get" class="search-form user-search"><input name="q" type="search" value="<?=e($q)?>" placeholder="Search by email address"><button class="button button-soft button-small">Search</button></form><div class="table-card"><div class="table-wrap"><table><thead><tr><th>ID</th><th>Email</th><th>Role</th><th>Status</th><th>Created</th><th>Action</th></tr></thead><tbody><?php if(!$users): ?><tr><td colspan="6"><div class="empty-state"><span>♙</span><strong>No users found</strong><small>Try a different email search.</small></div></td></tr><?php else:foreach($users as $u): ?><tr><td class="job-id">#<?=str_pad((string)$u['id'],4,'0',STR_PAD_LEFT)?></td><td><div class="file-cell"><span class="avatar mini"><?=e(strtoupper(substr($u['email'],0,1)))?></span><strong><?=e($u['email'])?></strong></div></td><td><?=e($u['role'])?></td><td><?=status_badge($u['status'])?></td><td><?=e(date('M j, Y',strtotime($u['created_at'])))?></td><td><a class="button button-small button-soft" href="/admin/user.php?id=<?=(int)$u['id']?>">View details</a></td></tr><?php endforeach;endif; ?></tbody></table></div></div><div class="modal-backdrop" id="create-user"><div class="modal-card"><a class="modal-close" href="/admin/users.php">×</a><div class="eyebrow">NEW ACCOUNT</div><h2>Create new user</h2><p class="muted">We’ll generate a temporary password and email it to the new account.</p><form method="post" class="form-stack"><input type="hidden" name="csrf" value="<?=e(csrf_token())?>"><input type="hidden" name="action" value="create"><label>Email address<input name="email" type="email" required placeholder="person@company.com"></label><label>Password <span class="optional">Generated on create</span><input value="Automatically generated" disabled></label><div class="field-row"><label>Status<select name="status"><option>Active</option><option>Suspended</option></select></label><label>Role<select name="role"><option>User</option><option>Admin</option></select></label></div><button class="button button-admin button-wide">Confirm &amp; create account <span>→</span></button></form></div></div><?php render_footer();
